package com.example.payment.architecturetest;

import static com.tngtech.archunit.core.domain.JavaClass.Predicates.resideInAnyPackage;
import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;

import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.junit.AnalyzeClasses;
import com.tngtech.archunit.junit.ArchTest;
import com.tngtech.archunit.lang.ArchRule;

@AnalyzeClasses(packages = "com.example.payment", importOptions = ImportOption.DoNotIncludeTests.class)
class LayerRulesTest {

    private static final String[] TECHNICAL = {
        "org.springframework..", "jakarta..", "javax..", "java.io..", "java.nio..", "java.net..", "java.sql.."
    };

    @ArchTest
    static final ArchRule domainDoesNotDependOnOuterLayers = noClasses()
            .that().resideInAPackage("com.example.payment.domain..")
            .should().dependOnClassesThat().resideInAnyPackage(
                    "com.example.payment.application..",
                    "com.example.payment.infrastructure..",
                    "com.example.payment.app..");

    @ArchTest
    static final ArchRule applicationDoesNotDependOnInfrastructureOrApp = noClasses()
            .that().resideInAPackage("com.example.payment.application..")
            .should().dependOnClassesThat().resideInAnyPackage(
                    "com.example.payment.infrastructure..",
                    "com.example.payment.app..");

    @ArchTest
    static final ArchRule infrastructureDoesNotDependOnApp = noClasses()
            .that().resideInAPackage("com.example.payment.infrastructure..")
            .should().dependOnClassesThat().resideInAPackage("com.example.payment.app..");

    @ArchTest
    static final ArchRule businessCodeAvoidsTechnicalApis = noClasses()
            .that().resideInAnyPackage("com.example.payment.domain..", "com.example.payment.application..")
            .should().dependOnClassesThat(resideInAnyPackage(TECHNICAL));
}
E
